#!/bin/bash
# Task 089 -- meshsim v1.25 section 8 verification (WORKER11): branch s8 at e65b14a (misalignment as UB, the gather unit's
# 128-bit copies for even k, the 256-byte boot ROM with its two-report dump; the sort arms its gathers by packets per value).
#  1. run_tests.sh's quick suite (tools/run_quick.sh, 8 at a time) and its full-mode extras (tools/run_full.sh, 4 at a time);
#  2. the full-size sort p4/uniform-k128 (WORKER8's runner kit, jar and sort image rebuilt from s8, HASHES updated),
#     compared against 1,360,082 cycles (DECISIONS-v1.25 s8c estimates about 130K fewer).
# The kit (wip/ at Java 17 with every image prebuilt; sortrunner/) is embedded below, SHA-256 checked; smoke-tested
# locally (run_quick on ctrl/cond/regdoc, run_p4 at n = 2,000: 242,445 cycles, from 246,447). Expected ~15 min.
set -u
cd "$(dirname "$0")/.."
RES=$PWD/results/089-w11-s8-verify; mkdir -p "$RES"
WANT=02209700db9f44c97c4aac8d461c3cb81d99c20de01584fd45e9713e7b577e00
W=/tmp/w11-089; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "$WANT" ] || { echo "kit sha256 mismatch (want $WANT)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
echo "start $(date -u) on $(hostname), $(nproc) threads"; java -version 2>&1 | head -1
cd "$W/wip/meshsim" || exit 2
P=8 ./run_quick.sh "$W/out"; RQ=$?
P=4 ./run_full.sh "$W/out"; RF=$?
cd "$W/sortrunner" || exit 2
printf 'p4/uniform-k128\n' > "$W/p4list"
bash ./run_p4.sh -j 1 -m 6g -l "$W/p4list" "$W/p4"; RS=$?
echo "run_quick.sh exit $RQ, run_full.sh exit $RF, run_p4.sh exit $RS at $(date -u)"
grep -h "TOTAL" "$W"/p4/VERDICT.txt 2>/dev/null | sed 's/^/p4 (was 1,360,082 cycles): /'
mkdir -p "$RES/p4"; cp "$W"/out/* "$RES/" 2>/dev/null; cp "$W"/p4/* "$RES/p4/" 2>/dev/null
cat "$W/out/VERDICT.txt" "$W/out/FULL-VERDICT.txt" "$W/p4/VERDICT.txt" 2>/dev/null
rm -rf "$W"
[ $RQ = 0 ] && [ $RF = 0 ] && [ $RS = 0 ]; exit $?
